PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE installation(id INTEGER PRIMARY KEY CHECK(id=1), owner_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE login_limits(key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, until_at INTEGER NOT NULL);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#24756e',sender_email TEXT NOT NULL DEFAULT '',inbox_email TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX workspace_inbox ON workspaces(inbox_email) WHERE inbox_email != '';
CREATE TABLE members(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','manager','sales','class_manager','teacher')),capacity INTEGER NOT NULL DEFAULT 100,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE courses(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,name TEXT NOT NULL,price REAL NOT NULL DEFAULT 0,description TEXT NOT NULL DEFAULT '',data TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,id));
CREATE TABLE classes(workspace_id TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,course_id TEXT NOT NULL,teacher_id TEXT,manager_id TEXT,capacity INTEGER NOT NULL DEFAULT 30,starts_at TEXT NOT NULL DEFAULT '',data TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,course_id) REFERENCES courses(workspace_id,id),FOREIGN KEY(workspace_id,teacher_id) REFERENCES members(workspace_id,user_id),FOREIGN KEY(workspace_id,manager_id) REFERENCES members(workspace_id,user_id));
CREATE TABLE campaigns(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,name TEXT NOT NULL,budget REAL NOT NULL DEFAULT 0,data TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,id));
CREATE TABLE sources(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,name TEXT NOT NULL,heat TEXT NOT NULL CHECK(heat IN ('hot','warm','cold')),PRIMARY KEY(workspace_id,id));
CREATE TABLE assignment_rules(workspace_id TEXT NOT NULL,id TEXT NOT NULL,source_id TEXT,course_id TEXT,assignee_id TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 10,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id),FOREIGN KEY(workspace_id,course_id) REFERENCES courses(workspace_id,id),FOREIGN KEY(workspace_id,assignee_id) REFERENCES members(workspace_id,user_id));
CREATE TABLE leads(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',source_id TEXT,campaign_id TEXT,course_id TEXT,class_id TEXT,assignee_id TEXT,stage TEXT NOT NULL DEFAULT 'new' CHECK(stage IN ('new','first_call','in_progress','won','irrelevant')),heat TEXT NOT NULL DEFAULT 'warm' CHECK(heat IN ('hot','warm','cold')),notes TEXT NOT NULL DEFAULT '',data TEXT NOT NULL DEFAULT '{}',marketing_consent INTEGER NOT NULL DEFAULT 0,consent_at TEXT,consent_text TEXT NOT NULL DEFAULT '',consent_source TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id),FOREIGN KEY(workspace_id,campaign_id) REFERENCES campaigns(workspace_id,id),FOREIGN KEY(workspace_id,course_id) REFERENCES courses(workspace_id,id),FOREIGN KEY(workspace_id,class_id) REFERENCES classes(workspace_id,id),FOREIGN KEY(workspace_id,assignee_id) REFERENCES members(workspace_id,user_id));
CREATE INDEX leads_owner ON leads(workspace_id,assignee_id,stage);
CREATE INDEX leads_email ON leads(workspace_id,email);
CREATE TABLE enrollments(workspace_id TEXT NOT NULL,id TEXT NOT NULL,lead_id TEXT NOT NULL,class_id TEXT NOT NULL,enrolled_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,lead_id),FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id),FOREIGN KEY(workspace_id,class_id) REFERENCES classes(workspace_id,id));
CREATE TABLE lessons(workspace_id TEXT NOT NULL,id TEXT NOT NULL,class_id TEXT NOT NULL,title TEXT NOT NULL,held_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,class_id) REFERENCES classes(workspace_id,id));
CREATE TABLE attendance(workspace_id TEXT NOT NULL,lesson_id TEXT NOT NULL,enrollment_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')),PRIMARY KEY(workspace_id,lesson_id,enrollment_id),FOREIGN KEY(workspace_id,lesson_id) REFERENCES lessons(workspace_id,id),FOREIGN KEY(workspace_id,enrollment_id) REFERENCES enrollments(workspace_id,id));
CREATE TABLE grades(workspace_id TEXT NOT NULL,id TEXT NOT NULL,enrollment_id TEXT NOT NULL,title TEXT NOT NULL,score REAL NOT NULL CHECK(score>=0 AND score<=100),graded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,enrollment_id) REFERENCES enrollments(workspace_id,id));
CREATE TABLE tasks(workspace_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,assignee_id TEXT NOT NULL,lead_id TEXT,class_id TEXT,due_at TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,assignee_id) REFERENCES members(workspace_id,user_id),FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id),FOREIGN KEY(workspace_id,class_id) REFERENCES classes(workspace_id,id));
CREATE INDEX tasks_due ON tasks(workspace_id,assignee_id,done,due_at);
CREATE TABLE finance(workspace_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('forecast','booked','receipt','expense_plan','expense')),amount REAL NOT NULL CHECK(amount>=0),course_id TEXT,campaign_id TEXT,date TEXT NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,course_id) REFERENCES courses(workspace_id,id),FOREIGN KEY(workspace_id,campaign_id) REFERENCES campaigns(workspace_id,id));
CREATE TABLE entity_types(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,name TEXT NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE fields(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,entity_type TEXT NOT NULL,label TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('text','number','date','select')),options TEXT NOT NULL DEFAULT '[]',required INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(workspace_id,id));
CREATE TABLE records(workspace_id TEXT NOT NULL,type_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,data TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,type_id) REFERENCES entity_types(workspace_id,id));
CREATE TABLE relations(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,from_type TEXT NOT NULL,from_id TEXT NOT NULL,to_type TEXT NOT NULL,to_id TEXT NOT NULL,label TEXT NOT NULL DEFAULT '',PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,from_type,from_id,to_type,to_id));
CREATE TABLE messages(workspace_id TEXT NOT NULL,id TEXT NOT NULL,lead_id TEXT,direction TEXT NOT NULL CHECK(direction IN ('in','out')),recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'service',status TEXT NOT NULL DEFAULT 'draft',provider_id TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,provider_id),FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id));
CREATE TABLE message_events(workspace_id TEXT NOT NULL,message_id TEXT NOT NULL,event_id TEXT NOT NULL,event TEXT NOT NULL,at TEXT NOT NULL,PRIMARY KEY(workspace_id,event_id),FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id));
CREATE TABLE activity(workspace_id TEXT NOT NULL,id TEXT NOT NULL,lead_id TEXT,user_id TEXT,action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id));
CREATE TABLE intake_keys(workspace_id TEXT NOT NULL,id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,source_id TEXT NOT NULL,campaign_id TEXT,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id),FOREIGN KEY(workspace_id,campaign_id) REFERENCES campaigns(workspace_id,id));
CREATE TABLE intake_events(workspace_id TEXT NOT NULL,event_id TEXT NOT NULL,lead_id TEXT NOT NULL,PRIMARY KEY(workspace_id,event_id),FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id));
CREATE TRIGGER enrollment_capacity BEFORE INSERT ON enrollments WHEN NEW.active=1 AND (SELECT COUNT(*) FROM enrollments WHERE workspace_id=NEW.workspace_id AND class_id=NEW.class_id AND active=1)>=(SELECT capacity FROM classes WHERE workspace_id=NEW.workspace_id AND id=NEW.class_id) BEGIN SELECT RAISE(ABORT,'CLASS_FULL'); END;
